<?php
namespace App\Http\Resources;
use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; use Illuminate\Support\Facades\Storage;
class EmployeeResource extends JsonResource { public function toArray(Request $request): array { $person=$this->person; return ['id'=>$this->id,'person_id'=>$this->person_id,'employee_number'=>$this->employee_number,'status'=>$this->status,'employment_type'=>$this->employment_type,'hired_at'=>$this->hired_at?->toDateString(),'dismissed_at'=>$this->dismissed_at?->toDateString(),'primary_department_id'=>$this->primary_department_id,'primary_position_id'=>$this->primary_position_id,'workload_rate'=>$this->workload_rate,'is_teacher'=>(bool)$this->is_teacher,'comment'=>$this->comment,'full_name'=>trim("{$person?->last_name} {$person?->first_name} {$person?->middle_name}"),'photo_path'=>$person?->photo_path,'photo_url'=>$person?->photo_path ? $request->getSchemeAndHttpHost().Storage::disk('public')->url($person->photo_path) : null,'person'=>new PersonResource($this->whenLoaded('person')),'teacher'=>new TeacherResource($this->whenLoaded('teacher')),'primary_department'=>new DepartmentResource($this->whenLoaded('primaryDepartment')),'primary_position'=>new PositionResource($this->whenLoaded('primaryPosition')),'assignments'=>EmployeeAssignmentResource::collection($this->whenLoaded('assignments')),'status_periods'=>EmployeeStatusPeriodResource::collection($this->whenLoaded('statusPeriods')),'current_status'=>$this->relationLoaded('statusPeriods') ? $this->statusOn(now()->toDateString()) : $this->status,'created_at'=>$this->created_at?->toISOString(),'updated_at'=>$this->updated_at?->toISOString()]; } }
